import { sql } from "drizzle-orm"
import { boolean, customType, index, integer, jsonb, pgTable, primaryKey, text, timestamp, uniqueIndex } from "drizzle-orm/pg-core"
import type { GameFamily, GameModeId, SingleplayerModeId } from "../../../shared/game/modes.js"
import type { Move } from "../../../shared/protocol.js"
import { user } from "./auth-schema.js"

// Accounts, sessions and sign-in methods. Generated by the auth CLI (see README), don't edit by hand
export * from "./auth-schema.js"

// The public side of an account
export const profile = pgTable("profile", {
  userId: text("user_id").primaryKey().references(() => user.id, { onDelete: "cascade" }),
  username: text("username").notNull(),
  // a few words about themselves, shown on their profile
  bio: text("bio").notNull().default(""),
  // experience: what their level is worked out from (see shared/progression.ts)
  xp: integer("xp").notNull().default(0),
  // their multiplayer rating; 1000 is where everyone starts
  elo: integer("elo").notNull().default(1000),
  // every game they have started in any mode, finished or not, and the seconds they have spent in them
  gamesStarted: integer("games_started").notNull().default(0),
  playSeconds: integer("play_seconds").notNull().default(0),
}, (table) => [
  // usernames are unique regardless of capitalisation
  uniqueIndex("profile_username_lower_idx").on(sql`lower(${table.username})`),
])

const bytea = customType<{ data: Buffer }>({ dataType: () => "bytea" })

// Uploaded profile photos. Kept in the database for now; file storage would take over once the site is hosted for real
export const avatar = pgTable("avatar", {
  userId: text("user_id").primaryKey().references(() => user.id, { onDelete: "cascade" }),
  contentType: text("content_type").notNull(),
  data: bytea("data").notNull(),
})

// One row per finished game of a signed-in player
export const gameResult = pgTable("game_result", {
  id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
  userId: text("user_id").notNull().references(() => user.id, { onDelete: "cascade" }),
  // Which singleplayer game it was: one whose boards never need a guess, or the classic one, with its mines
  // wherever chance put them. Every result from before there was a choice is a classic one
  mode: text("mode").$type<SingleplayerModeId>().notNull().default("classic"),
  rows: integer("rows").notNull(),
  cols: integer("cols").notNull(),
  mines: integer("mines").notNull(),
  won: boolean("won").notNull(),
  durationSeconds: integer("duration_seconds").notNull(),
  // the exact time, for a game the server ran; null for one from before it did
  durationMs: integer("duration_ms"),
  // The server ran the game itself, so the result can be trusted: only these are on the leaderboards.
  // The rows without it are from when the browser reported its own results
  verified: boolean("verified").notNull().default(false),
  // kept off the leaderboards: by an admin, or because it was too fast to have been a person playing
  hidden: boolean("hidden").notNull().default(false),
  hiddenReason: text("hidden_reason"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
}, (table) => [
  index("game_result_user_idx").on(table.userId),
])

// A multiplayer game someone cleared: one row per player who finished. The leaderboards are built from these,
// because the server runs those games itself and so the times can be trusted
export const multiplayerResult = pgTable("multiplayer_result", {
  id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
  userId: text("user_id").notNull().references(() => user.id, { onDelete: "cascade" }),
  rows: integer("rows").notNull(),
  cols: integer("cols").notNull(),
  mines: integer("mines").notNull(),
  durationMs: integer("duration_ms").notNull(),
  mineHits: integer("mine_hits").notNull(),
  // kept off the leaderboards: by an admin, or because it was too fast to have been a person playing
  hidden: boolean("hidden").notNull().default(false),
  hiddenReason: text("hidden_reason"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
}, (table) => [
  index("multiplayer_result_board_idx").on(table.rows, table.cols, table.mines, table.durationMs),
])

// A player's go at one day's challenge. The row appears when they first start that day, which is when their
// clock starts; the result is filled in when they clear the board
export const dailyAttempt = pgTable("daily_attempt", {
  userId: text("user_id").notNull().references(() => user.id, { onDelete: "cascade" }),
  // YYYY-MM-DD, in UTC
  date: text("date").notNull(),
  startedAt: timestamp("started_at").notNull(),
  durationMs: integer("duration_ms"),
  mineHits: integer("mine_hits"),
  // kept off the leaderboards: by an admin, or because it was too fast to have been a person playing
  hidden: boolean("hidden").notNull().default(false),
  hiddenReason: text("hidden_reason"),
}, (table) => [
  primaryKey({ columns: [table.userId, table.date] }),
])

// Every game the server has run, for each player who was in it, move by move, whatever kind of game it was.
// With the board's layout beside the moves, a game can be played back exactly as it went, which is how a result
// that looks wrong can be looked into
export const gameRecord = pgTable("game_record", {
  id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
  userId: text("user_id").notNull().references(() => user.id, { onDelete: "cascade" }),
  // where it was played: alone, in the day's challenge, or in a room (see shared/game/modes.ts)
  kind: text("kind").$type<GameFamily>().notNull(),
  // The game it was, which says what rules to play it back by. (The default is what every game was before there
  // were others to tell apart: the migration that added this filled it in for those.)
  mode: text("mode").$type<GameModeId>().notNull().default("classic"),
  // the same for every player of one multiplayer game
  match: text("match").notNull(),
  // whether the game counted towards ratings
  rated: boolean("rated").notNull().default(false),
  rows: integer("rows").notNull(),
  cols: integer("cols").notNull(),
  mines: integer("mines").notNull(),
  // where the mines were: one character per cell, row after row, "1" a mine and "0" not
  layout: text("layout").notNull(),
  // the cell the board was opened on
  openRow: integer("open_row").notNull(),
  openCol: integer("open_col").notNull(),
  // how the game ended for this player: a PlayerOutcome, or "abandoned" for a singleplayer game thrown away
  outcome: text("outcome").notNull(),
  durationMs: integer("duration_ms").notNull(),
  mineHits: integer("mine_hits").notNull(),
  // A multiplayer game: where this player came, out of how many, and how far it moved their rating (null where
  // ratings didn't move: an unrated game, or one played alone). All null for any other kind of game, and for
  // multiplayer games from before these were kept
  place: integer("place"),
  players: integer("players"),
  ratingChange: integer("rating_change"),
  // the fewest clicks the board could be cleared in from its opening
  bv: integer("bv").notNull(),
  moves: jsonb("moves").$type<Move[]>().notNull(),
  // looked too fast to have been a person playing, and why
  suspect: boolean("suspect").notNull().default(false),
  suspectReason: text("suspect_reason"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
}, (table) => [
  index("game_record_user_idx").on(table.userId, table.createdAt),
  index("game_record_match_idx").on(table.match),
])
